"""Durable sessions, replay high-water mark and transactional forwarding outbox."""
import json
import math
import secrets
import sqlite3
import time

from .protocol import Rejected, authenticate, integer, nonce, sign

MAX_AGE_MS = 30_000
MAX_SAMPLE_AGE_MS = 15_000
SESSION_MS = 300_000


def validate_data(data, sequence):
    if not isinstance(data, dict) or len(data) > 64:
        raise Rejected("DATA_SCHEMA")
    # These names are exclusively generated by this verifier, never the sender.
    if any(k.startswith(("auth_", "integrity_", "guard_")) or k in ("last_verified_at", "sample_age_ms") for k in data):
        raise Rejected("RESERVED_FIELD")
    if data.get("sequence") != sequence or type(data.get("sequence")) is not int:
        raise Rejected("SEQUENCE_MISMATCH")
    for field in ("blink_count", "yawn_count", "blink_window_count", "yawn_window_count", "uptime_ms", "boot_id"):
        integer(data, field, 0, 0xffffffff)
    for field in ("driver_present", "eyes_valid", "mouth_valid", "perclos_valid", "perclos_window_ready"):
        if type(data.get(field)) is not bool:
            raise Rejected("DATA_SCHEMA")
    for field, valid in (("eyes_closed", "eyes_valid"), ("mouth_open", "mouth_valid")):
        if (data[valid] and type(data.get(field)) is not bool) or (not data[valid] and data.get(field) is not None):
            raise Rejected("DATA_VALIDITY")
    for field, valid in (("perclos", "perclos_valid"), ("eye_closed_probability", "eyes_valid"),
                         ("mouth_open_probability", "mouth_valid")):
        value = data.get(field)
        if data[valid]:
            if type(value) not in (int, float) or not math.isfinite(value) or not 0 <= value <= 1:
                raise Rejected("DATA_RANGE")
        elif value is not None:
            raise Rejected("DATA_VALIDITY")
    # Reject nested/unbounded values; telemetry is a flat key/value map.
    for key, value in data.items():
        if not isinstance(key, str) or len(key) > 64 or type(value) not in (str, int, float, bool, type(None)):
            raise Rejected("DATA_SCHEMA")
        if isinstance(value, str) and len(value) > 256:
            raise Rejected("DATA_SCHEMA")
        if type(value) is float and not math.isfinite(value):
            raise Rejected("DATA_RANGE")


class Verifier:
    def __init__(self, database, devices, clock=None):
        self.devices = devices
        self.clock = clock or (lambda: int(time.time() * 1000))
        self.db = sqlite3.connect(database)
        self.db.row_factory = sqlite3.Row
        self.db.executescript("""
            PRAGMA journal_mode=WAL;
            PRAGMA synchronous=FULL;
            CREATE TABLE IF NOT EXISTS sessions(
                device TEXT PRIMARY KEY, boot TEXT, request TEXT, sid TEXT,
                expires INTEGER, last_seq INTEGER DEFAULT 0);
            CREATE TABLE IF NOT EXISTS requests(
                device TEXT, request TEXT, created INTEGER, PRIMARY KEY(device,request));
            CREATE TABLE IF NOT EXISTS outbox(
                id INTEGER PRIMARY KEY, device TEXT, sid TEXT, sequence INTEGER,
                digest TEXT, sent_at INTEGER, measured_at INTEGER, telemetry TEXT,
                status TEXT DEFAULT 'pending', UNIQUE(device,sid,sequence));
            CREATE TABLE IF NOT EXISTS counters(reason TEXT PRIMARY KEY, count INTEGER);
        """)

    def close(self):
        self.db.close()

    def count(self, reason):
        with self.db:
            self.db.execute("INSERT INTO counters VALUES(?,1) ON CONFLICT(reason) DO UPDATE SET count=count+1", (reason,))

    def counts(self):
        return dict(self.db.execute("SELECT reason,count FROM counters"))

    def handle(self, wire, device_id, expected_type):
        try:
            body, digest = authenticate(wire, self.devices)
            if body.get("v") != 1 or type(body.get("v")) is not int or body.get("device_id") != device_id or body.get("type") != expected_type:
                raise Rejected("CONTEXT_MISMATCH")
            now = self.clock()
            sent_at = integer(body, "sent_at_ms")
            if sent_at < now - MAX_AGE_MS or sent_at > now + 5000:
                raise Rejected("STALE_OR_FUTURE")
            nonce(body, "boot_id")
            if expected_type == "hello":
                response = self._session(body, now)
                self.count("SESSION")
                return {"status": "SESSION", "response": response}
            if expected_type != "sample":
                raise Rejected("MESSAGE_TYPE")
            result = self._sample(body, digest, now, sent_at)
            self.count(result["status"])
            return result
        except Rejected as exc:
            self.count(exc.reason)
            return {"status": exc.reason}

    def _response(self, device_id, **fields):
        device = self.devices[device_id]
        body = {"v": 1, "device_id": device_id, "key_id": device["key_id"],
                "sent_at_ms": self.clock(), **fields}
        return sign(body, bytes.fromhex(device["hmac_key_hex"]))

    def _session(self, body, now):
        request = nonce(body, "request_id")
        device = body["device_id"]
        with self.db:
            self.db.execute("DELETE FROM requests WHERE created < ?", (now - 2 * MAX_AGE_MS,))
            seen = self.db.execute("SELECT 1 FROM requests WHERE device=? AND request=?", (device, request)).fetchone()
            current = self.db.execute("SELECT * FROM sessions WHERE device=?", (device,)).fetchone()
            if seen:
                if not current or current["request"] != request or current["boot"] != body["boot_id"] or current["expires"] <= now:
                    raise Rejected("OLD_HELLO")
                # QoS retry must not reset the replay high-water mark.
                sid, expires = current["sid"], current["expires"]
            else:
                sid, expires = secrets.token_hex(16), now + SESSION_MS
                self.db.execute("INSERT INTO requests VALUES(?,?,?)", (device, request, now))
                self.db.execute("INSERT INTO sessions VALUES(?,?,?,?,?,0) ON CONFLICT(device) DO UPDATE SET "
                                "boot=excluded.boot,request=excluded.request,sid=excluded.sid,expires=excluded.expires,last_seq=0",
                                (device, body["boot_id"], request, sid, expires))
        return self._response(device, type="session", boot_id=body["boot_id"], request_id=request,
                              session_id=sid, expires_at_ms=expires)

    def _sample(self, body, digest, now, sent_at):
        sid = nonce(body, "session_id")
        sequence = integer(body, "sequence", 1, 0xffffffff)
        age = integer(body, "sample_age_ms", 0, MAX_SAMPLE_AGE_MS)
        # The sample itself must be fresh, not just its freshly signed envelope.
        if sent_at - age < now - MAX_AGE_MS:
            raise Rejected("SAMPLE_TOO_OLD")
        data = body.get("data")
        validate_data(data, sequence)
        device = body["device_id"]
        with self.db:
            session = self.db.execute("SELECT * FROM sessions WHERE device=?", (device,)).fetchone()
            if not session or session["sid"] != sid or session["boot"] != body["boot_id"]:
                raise Rejected("SESSION_INVALID")
            if session["expires"] <= now:
                raise Rejected("SESSION_EXPIRED")
            if sequence <= session["last_seq"]:
                old = self.db.execute("SELECT digest,status,id FROM outbox WHERE device=? AND sid=? AND sequence=?",
                                      (device, sid, sequence)).fetchone()
                if old and old["digest"] == digest:
                    result = {"status": "DUPLICATE"}
                    if old["status"] == "sent":
                        result["response"] = self.forwarded_ack(device, sid, sequence, body["boot_id"])
                    return result
                raise Rejected("REPLAY_OR_SEQUENCE_CONFLICT")
            telemetry = {**data, "integrity_status": "VERIFIED", "integrity_reason": "OK",
                         "auth_device_id": device, "auth_key_id": body["key_id"],
                         "auth_session_id": sid, "auth_sequence": sequence,
                         "last_verified_at": now, "sample_age_ms": age}
            # An administrator may provision a demo identity on the real broker.
            # Its valid samples exercise replay protection but never enter the
            # production forwarding queue. This policy comes from server config,
            # never from the received payload, and is stored in the same transaction.
            status = "demo" if self.devices[device].get("demo_only") is True else "pending"
            cursor = self.db.execute("INSERT INTO outbox(device,sid,sequence,digest,sent_at,measured_at,telemetry,status) "
                                     "VALUES(?,?,?,?,?,?,?,?)", (device, sid, sequence, digest, sent_at,
                                                               sent_at - age, json.dumps(telemetry, ensure_ascii=False), status))
            self.db.execute("UPDATE sessions SET last_seq=? WHERE device=?", (sequence, device))
        return {"status": "ACCEPTED", "outbox_id": cursor.lastrowid}

    def forwarded_ack(self, device, sid, sequence, boot):
        return self._response(device, type="ack", status="FORWARDED", session_id=sid, sequence=sequence, boot_id=boot)

    def next_pending(self):
        # Old data is not replayed onto a dashboard after a long cloud outage.
        with self.db:
            self.db.execute("UPDATE outbox SET status='expired' WHERE status='pending' AND measured_at < ?",
                            (self.clock() - MAX_AGE_MS,))
        return self.db.execute("SELECT * FROM outbox WHERE status='pending' ORDER BY id LIMIT 1").fetchone()

    def mark_forwarded(self, outbox_id):
        with self.db:
            row = self.db.execute("SELECT * FROM outbox WHERE id=? AND status='pending'", (outbox_id,)).fetchone()
            if not row:
                return None
            self.db.execute("UPDATE outbox SET status='sent' WHERE id=?", (outbox_id,))
            session = self.db.execute("SELECT * FROM sessions WHERE device=? AND sid=?", (row["device"], row["sid"])).fetchone()
            # Keep the most recent sessions/audit footprint bounded.
            self.db.execute("DELETE FROM outbox WHERE status!='pending' AND sent_at < ?", (self.clock() - 86_400_000,))
        self.count("FORWARDED")
        if session:
            return row["device"], self.forwarded_ack(row["device"], row["sid"], row["sequence"], session["boot"])
        return None
